export function googleSignInPage(){return `<!doctype html><html lang="zh-Hans"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google 会话授权</title><script src="/google-authorization/signin.js" defer></script><style>body{margin:0;background:#f4f5ef;color:#193b30;font:16px/1.7 system-ui}main{max-width:640px;margin:40px auto;padding:28px;background:white;border-radius:12px}label{display:block;margin-top:16px}input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #bacbbb;border-radius:8px;font:inherit}button{padding:10px 18px;border:0;border-radius:8px;background:#193b30;color:white;margin:20px 8px 8px 0;cursor:pointer}button:disabled{opacity:.5}#message{white-space:pre-wrap}a{color:#245e49}</style></head><body><main><h1>Google 会话授权</h1><p>此页面仅供站点所有者使用，不显示远程桌面。后台 Chrome 访问 Google 官方登录页面；Google 可能要求你在手机上确认。</p><p>密码通过 HTTPS 临时转交登录程序，不写入数据库、日志或浏览器归档。Sites、Render 和浏览器执行环境会在本次请求处理中接触密码；这不是 Google 官方的密码输入页面。</p><form id="signin" autocomplete="off"><label for="account">与 BundleFoundry 相同的 Google 邮箱</label><input id="account" type="email" required maxlength="254" autocomplete="off"><label for="password">Google 密码</label><input id="password" type="password" required maxlength="1024" autocomplete="off"><button id="submit" type="submit">登录并等待手机验证</button><button id="cancel" type="button" disabled>取消登录</button></form><p id="message" role="status" aria-live="polite">提交后，请查看手机上的 Google 登录确认。Google 若要求其他验证，页面会明确提示。</p><p><a href="/">返回领取中心</a></p></main></body></html>`;}

export const googleSignInScript=`
const form=document.getElementById('signin'),message=document.getElementById('message'),submit=document.getElementById('submit'),cancel=document.getElementById('cancel');
let id=null,timer=null,committing=false;
const labels={forbidden:'请使用本站所有者身份登录。',account_mismatch:'邮箱与已配置的 BundleFoundry 账号不一致。',invalid_login_input:'请填写正确的邮箱和密码。',login_in_progress:'已有登录正在进行，请先取消或等待。',google_session_rejected:'Google 拒绝了这次登录，未保存新会话。',invalid_password:'Google 未接受密码，请重新尝试。',additional_verification:'Google 要求输入验证码或执行其他验证，当前不能仅靠手机确认完成。',upstream_run_incomplete:'授权可能已保存，但云端失效测试未通过。',browser_action_incomplete:'登录暂未完成，请稍后重试。'};
async function call(path,body){const r=await fetch(path,{credentials:'same-origin',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const data=await r.json();if(!r.ok)throw Error(labels[data.error]||'操作未完成，请稍后重试。');return data;}
function stop(){clearTimeout(timer);submit.disabled=false;cancel.disabled=true;}
async function refresh(){try{const state=await call('/api/google-browser/state');id=state.id;if(state.phase==='signing_in')message.textContent=state.agent_online?'正在通过 Google 官方页面登录…':'等待登录执行环境连接…';if(state.phase==='waiting_for_phone')message.textContent='请查看手机上的 Google 登录确认。'+(state.challenge_number?'如 Google 要求选择数字，请选择 '+state.challenge_number+'。':'')+'确认后会自动继续。';if(state.phase==='additional_verification')message.textContent=labels.additional_verification;if(state.phase==='error'){message.textContent=labels[state.error]||'Google 登录未完成。';stop();return;}if(['expired','closed'].includes(state.phase)){message.textContent='登录已取消或超时，未替换已保存的会话。';stop();return;}if(state.phase==='captured'&&!committing){committing=true;message.textContent='登录已完成，正在关闭浏览器、加密保存并测试云端自动重登录…';await call('/api/google-browser/commit',{});const result=await call('/api/google-browser/test',{});if(result.session_recovery_test?.site_session_valid_after_login!==true)throw Error('授权已保存，云端测试尚未通过。');message.textContent='云端失效测试通过：系统已自动复用 Google 会话重新登录 BundleFoundry。';stop();return;}}catch(error){message.textContent=error.message;if(committing){stop();return;}}timer=setTimeout(refresh,1500);}
form.addEventListener('submit',async event=>{event.preventDefault();submit.disabled=true;const input=document.getElementById('password');let password=input.value;input.value='';try{const state=await call('/api/google-browser/signin',{account:document.getElementById('account').value.trim(),password});password='';id=state.id;committing=false;cancel.disabled=false;refresh();}catch(error){password='';message.textContent=error.message;stop();}});
cancel.addEventListener('click',async()=>{try{await call('/api/google-browser/input',{id,operation:'cancel'});message.textContent='已取消登录。';stop();}catch(error){message.textContent=error.message;}});
call('/api/google-browser/state').then(state=>{if(state.mode==='credentials'&&['signing_in','waiting_for_phone','additional_verification','captured'].includes(state.phase)){id=state.id;submit.disabled=true;cancel.disabled=false;refresh();}else if(state.phase==='error'){message.textContent=labels[state.error]||'上一轮 Google 登录未完成。';}}).catch(error=>{message.textContent=error.message;});
`;
